set role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000201","aal":"aal1"}',false);
select public.send_consultation_message(auth.uid(),'A test follow-up question');
select public.request_consultation_meeting('Test availability in East Africa Time');
do $$begin perform public.save_application_form('{"email":"legacy@example.invalid"}',false);raise exception 'Premature application form';exception when raise_exception then if sqlerrm<>'Application locked' then raise;end if;end $$;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000202","aal":"aal1"}',false);
select public.test_assert((select count(*)=0 from public.consultation_messages),'follow-ups isolated');
do $$begin perform public.send_consultation_message('00000000-0000-4000-8000-000000000201','Forged reply');raise exception 'Cross-user message';exception when raise_exception then if sqlerrm<>'Access denied' then raise;end if;end $$;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000102","aal":"aal1"}',false);
do $$begin perform public.schedule_consultation_meeting('00000000-0000-4000-8000-000000000201',now()+interval '1 day',now()+interval '1 day 45 minutes','Africa/Dar_es_Salaam','https://meet.google.com/abc-defg-hij');raise exception 'Unassigned advisor scheduled';exception when raise_exception then if sqlerrm<>'Access denied' then raise;end if;end $$;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000103","aal":"aal1"}',false);
select set_config('test.meeting',public.schedule_consultation_meeting('00000000-0000-4000-8000-000000000201',now()+interval '1 day',now()+interval '1 day 45 minutes','Africa/Dar_es_Salaam','https://meet.google.com/abc-defg-hij')::text,false);
do $$begin perform public.finish_consultation_meeting(current_setting('test.meeting')::uuid,'completed','Test complete');raise exception 'Future meeting completed';exception when raise_exception then if sqlerrm<>'Meeting has not started' then raise;end if;end $$;
do $$begin perform public.schedule_consultation_meeting('00000000-0000-4000-8000-000000000201',now()+interval '1 day 15 minutes',now()+interval '1 day 1 hour','Africa/Dar_es_Salaam','https://meet.google.com/abc-defg-hij');raise exception 'Overlapping meeting';exception when raise_exception then if sqlerrm<>'Meeting overlaps an existing booking' then raise;end if;end $$;
reset role;
-- Simulate elapsed time only in this disposable database.
update public.consultation_meetings set starts_at=now()-interval '1 hour',ends_at=now()-interval '15 minutes' where id=current_setting('test.meeting')::uuid;
set role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000103","aal":"aal1"}',false);
select public.finish_consultation_meeting(current_setting('test.meeting')::uuid,'completed','Consultation completed in disposable fixture');
select public.test_assert((select completed_at is not null from public.consultation_cases where user_id='00000000-0000-4000-8000-000000000201'),'completed meeting unlocks application');
select public.test_assert((select count(*)=4 from public.document_requests where user_id='00000000-0000-4000-8000-000000000201'),'later document requests created');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000201","aal":"aal1"}',false);
select public.save_application_form('{"firstName":"Student","email":"legacy@example.invalid"}',false);
select public.test_assert((select count(*)=1 from public.application_form_drafts),'partial draft saved');
do $$begin perform public.save_application_form('{"email":"legacy@example.invalid","role":"admin"}',false);raise exception 'Unexpected field stored';exception when raise_exception then if sqlerrm<>'Unexpected form field' then raise;end if;end $$;
select set_config('test.full_data','{"firstName":"Student","lastName":"Test","email":"legacy@example.invalid","phone":"+255700000000","studyInterest":"Engineering","programme":"Engineering","residence":"Tanzania","cityStreet":"Test city","highestEducation":"Bachelor","institutionName":"Test institution","institutionCountry":"Tanzania","graduationYear":"2026","guardianFirstName":"Guardian","guardianLastName":"Test","guardianPhone":"+255700000001","guardianRelation":"Parent","guardianPermission":true}',false);
select set_config('test.declaration',public.save_application_form(current_setting('test.full_data')::jsonb,true)::text,false);
select public.test_assert(public.save_application_form(current_setting('test.full_data')::jsonb,true)::text=current_setting('test.declaration'),'identical declaration is idempotent');
select public.test_assert((select version='2026-11-18-application-v1' and accepted_at<=now() from public.application_declarations),'server stamps declaration version/time');
select set_config('test.accepted_at',(select accepted_at::text from public.application_declarations where id=current_setting('test.declaration')::uuid),false);
select public.test_assert((select data->>'middleName'='' and data->>'guardianEmail'='' and data->>'guardianDob'='' and data->>'maritalStatus'='' from public.application_declarations where id=current_setting('test.declaration')::uuid),'omitted optional answers normalized for PDF schema');
select public.test_assert((select current_declaration_id=current_setting('test.declaration')::uuid from public.consultation_cases),'current declaration points to first acceptance');
do $$declare invalid_year text;begin
 foreach invalid_year in array array['1949','2100','2026junk','2026.5'] loop
  begin perform public.save_application_form(jsonb_set(current_setting('test.full_data')::jsonb,'{graduationYear}',to_jsonb(invalid_year)),true);raise exception 'Invalid year accepted';exception when raise_exception then if sqlerrm<>'Invalid graduation year' then raise;end if;end;
 end loop;
end $$;
do $$begin perform public.save_application_form(jsonb_set(current_setting('test.full_data')::jsonb,'{guardianPermission}','"true"'::jsonb),true);raise exception 'String permission accepted';exception when raise_exception then if sqlerrm<>'Invalid guardian permission' then raise;end if;end $$;
do $$begin perform public.save_application_form(jsonb_set(current_setting('test.full_data')::jsonb,'{guardianEmail}','"not-an-email"'::jsonb),true);raise exception 'Invalid email accepted';exception when raise_exception then if sqlerrm<>'Invalid email' then raise;end if;end $$;
do $$begin perform public.save_application_form(jsonb_set(current_setting('test.full_data')::jsonb,'{guardianDob}','"2026-02-29"'::jsonb),true);raise exception 'Invalid date accepted';exception when raise_exception then if sqlerrm<>'Invalid guardian date' then raise;end if;end $$;
select set_config('test.declaration_b',public.save_application_form(jsonb_set(current_setting('test.full_data')::jsonb,'{programme}','"Medicine"'::jsonb),true)::text,false);
select public.test_assert((select current_declaration_id=current_setting('test.declaration_b')::uuid from public.consultation_cases),'changed answers become current');
select set_config('test.restored_a',public.save_application_form(current_setting('test.full_data')::jsonb,true)::text,false);
select public.test_assert(current_setting('test.restored_a')<>current_setting('test.declaration'),'A-B-A creates a new acceptance for restored A');
select public.test_assert((select current_declaration_id=current_setting('test.restored_a')::uuid from public.consultation_cases),'current declaration points to restored A, not B');
select public.test_assert((select count(*)=3 from public.application_declarations),'all three immutable acceptance snapshots retained');
select public.test_assert((select accepted_at::text=current_setting('test.accepted_at') from public.application_declarations where id=current_setting('test.declaration')::uuid),'original acceptance timestamp unchanged');
select public.test_assert((select a.data=b.data and a.snapshot_hash=b.snapshot_hash and b.accepted_at>=a.accepted_at from public.application_declarations a cross join public.application_declarations b where a.id=current_setting('test.declaration')::uuid and b.id=current_setting('test.restored_a')::uuid),'restored A has matching answers and a separate acceptance');
select public.test_assert(public.save_application_form(current_setting('test.full_data')::jsonb,true)::text=current_setting('test.restored_a'),'consecutive retry reuses current acceptance');
do $$begin update public.consultation_cases set current_declaration_id=current_setting('test.declaration_b')::uuid;raise exception 'Current declaration tampered';exception when insufficient_privilege then null;end $$;
do $$begin update public.application_declarations set accepted_at=now()-interval '1 year';raise exception 'Declaration tampered';exception when insufficient_privilege then null;end $$;
select public.request_consultation_meeting('Further test consultation with no second fee');
select public.test_assert((select count(*)=2 from public.meeting_requests),'multiple meetings can be requested');
select public.test_assert((select fee_tzs=50000 from public.consultation_cases),'follow-up does not add a fee');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000202","aal":"aal1"}',false);
select public.test_assert((select count(*)=0 from public.application_declarations),'declaration snapshot isolated');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000102","aal":"aal1"}',false);
select public.test_assert((select count(*)=0 from public.application_declarations),'unassigned advisor cannot read submitted declarations');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000103","aal":"aal1"}',false);
select public.test_assert((select count(*)=3 from public.application_declarations),'authorized staff can read accepted PDF snapshots');
reset role;
select public.test_assert((select count(distinct entity_id)=3 and bool_and(entity_id in(current_setting('test.declaration')::uuid,current_setting('test.declaration_b')::uuid,current_setting('test.restored_a')::uuid)) from private.integration_events where event='application.form_received'),'A-B-A alerts identify all three immutable acceptances');
select public.test_assert((select count(*)>0 and bool_and(acceptances=3 and events=3) from (select channel,recipient,count(distinct entity_id) acceptances,count(*) events from private.integration_events where event='application.form_received' group by channel,recipient) deliveries),'each recipient receives three changed acceptance alerts without retry duplicates');
select public.test_assert((select count(*)=1 from private.notification_outbox where event='meeting_scheduled'),'real meeting email queued exactly once');
select 'MEETINGS, FOLLOW UPS AND DECLARATIONS PASSED' as result;
